"""Generate all robust-transfer claims directly from retained case tables."""
from common4 import *
from make_article import table,G,F,A
from figure_style import journal_layout
import numpy as np,pandas as pd,matplotlib.pyplot as plt

def main():
    D=ROOT/'results/robust_transfer';f=pd.read_csv(D/'cases.csv');p=f[(f.budget==8)&f.delivery.eq('full')&(f.halfwidth_s==.5)&f.sensor.eq('ideal')];s=p.groupby(['prior_condition','method']).RMSE_Wh.mean();control=float(s.loc[('measurement','PCHIP')]);rows=[]
    for condition in ['original','smooth','step','flat']:
        vals=[float(s.loc[(condition,m)]) for m in ['global','local','validated']];rows.append([condition.capitalize(),*[f'{x:.4f}' for x in vals],f'{control:.4f}'])
    table('robust_primary.tex','AMOVFLY prespecified primary: all 247 unique eligible test records, eight received readings, ideal numerical counter and 0.5 s time boxes. Continuous RMSE (Wh), equal record weights. All four methods share each history\'s radius; its mean is 3.0007 Wh. The prior distortions are controlled stresses, not measured field drift.',['Prior','Global','Local','Query-selected','PCHIP'],rows,label='tab:robustprimary')
    v=p[p.prior_condition.eq('original')&p.method.eq('validated')].set_index('record_id');q=p[p.method.eq('PCHIP')].set_index('record_id');delta=v.RMSE_Wh-q.RMSE_Wh;paired=pd.DataFrame(dict(difference=delta,date=v.date));clusters=paired.groupby('date').difference.agg(['sum','count']);rng=np.random.default_rng(2026102709);idx=rng.integers(0,len(clusters),size=(5000,len(clusters)));boot=clusters['sum'].to_numpy()[idx].sum(axis=1)/clusters['count'].to_numpy()[idx].sum(axis=1);ci=np.quantile(boot,[.025,.975]);n=dict(primary_PCHIP_Wh=control,primary_validated_Wh=float(v.RMSE_Wh.mean()),primary_delta_Wh=float(delta.mean()),date_cluster_descriptive_interval_Wh=ci.tolist(),records_worse=int((delta>1e-10).sum()),records_tied=int((abs(delta)<=1e-10).sum()),worst_record_increase_Wh=float(delta.max()),worst_record_decrease_Wh=float(delta.min()),mean_weight=float(v.weight.mean()),all_main_cases=len(f),corrected_cases=int((~f.method.eq('nominal_uncorrected')).sum()))
    rows=[]
    for aircraft,z in p.groupby('aircraft'):
        a=z[z.method.eq('PCHIP')];b=z[z.prior_condition.eq('original')&z.method.eq('validated')];rows.append([aircraft,len(a),f'{a.RMSE_Wh.mean():.4f}',f'{b.RMSE_Wh.mean():.4f}',f'{a.radius_Wh.mean():.4f}'])
    table('robust_aircraft.tex','Primary results by the three source aircraft identifiers. These are not independent collection campaigns or three airframe families.',['ID','Records','PCHIP','Query-selected','Mean $R$'],rows,label='tab:robustaircraft')
    rows=[]
    for key,z in f.groupby(['budget','delivery','halfwidth_s','sensor']):
        B,delivery,h,sensor=key;a=z[z.method.eq('PCHIP')];b=z[z.prior_condition.eq('original')&z.method.eq('validated')];rows.append([B,int(a.received_queries.iloc[0]),'Full' if delivery=='full' else 'Loss',f'{h:g}',sensor,f'{a.RMSE_Wh.mean():.4f}',f'{b.RMSE_Wh.mean():.4f}',f'{a.radius_Wh.mean():.4f}'])
    table('full_robust.tex','Every AMOVFLY measurement condition. Requested/received query counts remain distinct under deterministic half-loss of interior readings. All rows use all 247 test records. Wh units apply to error and radius. Full prior-condition results and refusals remain in the released CSVs.',['$B$','Recv.','Delivery','$h$','Sensor','PCHIP','Selected','$R$'],rows,long=True,label='tab:fullrobust')
    c=pd.read_csv(D/'calibration_sweep.csv');rows=[]
    for (gamma,bias),z in c.groupby(['declared_gain','declared_bias_W']):rows.append([f'{100*gamma:g}',f'{bias:g}',int(z.reference_in_class.sum()),len(z),f'{z.radius_Wh.mean():.4f}'])
    table('robust_calibration.tex',r'Constant +5\% power gain and +5 W bias, plus bounded 0.02 Wh reading drift, on all 247 test references. These virtual mechanisms are separate from the time-varying bounded grid. An apparently feasible nominal class can exclude the actual reference. $R$ is sharp only for the rectangular energy-box relaxation.',['Declared gain \\%','Bias W','Reference inside','Total','Mean $R$ Wh'],rows,label='tab:robustcalibration')
    rows=[]
    cap=pd.read_csv(D/'cap_sensitivity.csv')
    for capvalue,z in cap.groupby('cap_W'):
        for method,w in z.groupby('method'):rows.append([int(capvalue),method,len(w),f'{w.RMSE_Wh.mean():.4f}',f'{w.radius_Wh.mean():.4f}'])
    table('robust_caps.tex','Prespecified cap sensitivities for the AMOVFLY primary histories. No cap is selected by these outcomes. The 4000 W primary remains in Table~\\ref{tab:robustprimary}.',['Cap W','Method','Records','RMSE Wh','Mean $R$ Wh'],rows,label='tab:robustcaps')
    dev=pd.read_csv(ROOT/'results/robust_development/summary.csv');rows=[]
    for dataset,z in dev[dev.budget.eq(8)].groupby('dataset'):
        ctl=z[z.method.eq('PCHIP')].RMSE_Wh.iloc[0]
        for condition in ['original','smooth','step','flat']:
            vals=z[z.prior_condition.eq(condition)].set_index('method').RMSE_Wh;rows.append(['Dev' if dataset=='development' else 'Solar',condition,*[f'{vals[m]:.4f}' for m in ['global','local','validated']],f'{ctl:.4f}'])
    table('robust_development.tex','Post-development B8 checks on all 440 earlier records and 161 already inspected solar windows, with 0.5 s boxes and ideal readings. Dev uses the previous platform/source weights; Solar uses window means. The 257-node proposal basis is fixed for this extension. These results do not replace the earlier registered comparisons. All 23,439 individual cases and all budgets remain in the executable artifact.',['Pool','Prior','Global','Local','Selected','PCHIP'],rows,label='tab:robustdevelopment')
    budget=pd.read_csv(D/'duplicate_reference_budget.csv');n.update(duplicate_choice_max_Wh=float(budget.reference_choice_peak_budget_Wh.max()),duplicate_choice_affected_records=int((budget.conflicting_time_groups>0).sum()))
    t=json.loads((ROOT/'results/robust_timing/gate.json').read_text());n['timing']=t;write(A/'robust_numbers.json',n)
    text=f'The query-selected method gives {n["primary_validated_Wh"]:.4f} Wh versus {control:.4f} Wh for PCHIP in the prespecified primary comparison (paired difference {n["primary_delta_Wh"]:+.6f} Wh). The descriptive date-cluster interval is [{ci[0]:+.6f}, {ci[1]:+.6f}] Wh; it resamples 21 observed dates, not independent campaigns. It is worse on {n["records_worse"]}/247 records, with a maximum increase of {n["worst_record_increase_Wh"]:.4f} Wh. Thus, selection does not establish superiority over current-reading interpolation. Its mean historical weight is {n["mean_weight"]:.3f}; all initialization and fallback records remain in the denominator.\\par\n'
    text+=f'Across all {len(f):,} main cases, the {n["corrected_cases"]:,} calibration-aware recoveries return checked centers and contain the numerical reference in their declared classes. The 2,964 nominal uncorrected controls all exclude that reference; their smaller radii are not evidence of greater accuracy assurance. No physical detection sensitivity is inferred. Removing interior queries and expanding the declared calibration bounds never reduces the computed radius in the matched checks. The 494 very large synthetic resets/outliers are rejected, but are not a labeled aircraft-fault benchmark.\\par\n'
    text+=f'Independent source replay checks all 829,021 electrical rows, while independent polynomial quadrature checks all 3,211 stored primary curves. Duplicate-time ambiguity affects {n["duplicate_choice_affected_records"]} test references; changing any retained duplicate power within its source range changes any reference prefix by at most {n["duplicate_choice_max_Wh"]:.6f} Wh under the declared interpolation. This is a numerical-reference budget, not an instrument-accuracy bound.\\par\n'
    text+=f'The new full-pipeline CPU benchmark includes calibration conversion, prior construction, leave-one-query-out selection when used, clipping and numerical checks. Across 56 duration-median source histories and seven repetitions, median latencies are {t["method_median_ms"]["PCHIP"]:.2f} ms (PCHIP), {t["method_median_ms"]["local"]:.2f} ms (local) and {t["method_median_ms"]["validated"]:.2f} ms (query-selected); corresponding 95th percentiles are {t["method_p95_ms"]["PCHIP"]:.2f}, {t["method_p95_ms"]["local"]:.2f} and {t["method_p95_ms"]["validated"]:.2f} ms. These measurements do not extend the earlier 6.32-fold clip/QP speedup to the additional selection stage or establish onboard performance.\n'
    interface=json.loads((ROOT/'audit/robust_interface_QA.json').read_text());text+=f'As a post-outcome diagnostic, excluding the single duplicate-ambiguous reference leaves 246 records and a paired selected-minus-PCHIP difference of {interface["posthoc_duplicate_exclusion_primary_delta_Wh"]:+.6f} Wh. The original 247-record primary result is unchanged. A conservative fixed-curve reference-choice budget for the full paired mean is {interface["all_record_fixed_curve_paired_delta_reference_budget_Wh"]:.6f} Wh, larger than the observed difference; its sign should not be generalized across export interpretations.\n'
    (G/'robust_interpretation.tex').write_text(text,encoding='utf-8')
    fig,axes=plt.subplots(1,2,figsize=(10,3.6));x=np.arange(4)
    for method,label,color in [('global','Global','#a5522a'),('local','Local','#176f78'),('validated','Query-selected','#587db3')]:axes[0].plot(x,[s.loc[(c,method)] for c in ['original','smooth','step','flat']],'o-',lw=1,ms=3,label=label,color=color)
    axes[0].axhline(control,color='#666666',ls='--',lw=1,label='Current PCHIP');axes[0].set(xticks=x,xticklabels=['Original','Smooth','Step','Flat'],ylabel='Continuous RMSE (Wh)',xlabel='Prior stress',title='247 held-out source records')
    z=c.groupby('declared_gain').agg(inside=('reference_in_class','mean'),radius=('radius_Wh','mean'));axes[1].plot(100*z.index,100*z.inside,'o-',color='#176f78');axes[1].set(xlabel='Declared gain bound (%)',ylabel='Reference inside class (%)',ylim=(-5,105),title='Bias bounds: 0, 2.5, 5, 10 W');axes[1].axvline(5,color='#666666',ls='--',lw=1)
    handles,labels=axes[0].get_legend_handles_labels();fig.legend(handles,labels,loc='lower center',bbox_to_anchor=(.5,-.01),ncol=4,frameon=False,fontsize=8);journal_layout(fig);fig.tight_layout(rect=[0,.16,1,1]);fig.savefig(F/'robust_transfer.png');plt.close(fig);print(json.dumps(n,indent=2))

if __name__=='__main__':main()
